#pragma once
int runTransient407(const char* input,const char* output){juce::ScopedJuceInitialiser_GUI gui;try{auto rows=juce::JSON::parse(juce::File(input));if(!rows.isArray())return 4071;juce::Array<juce::var> results;juce::AudioFormatManager formats;formats.registerBasicFormats();TransientAnalysis::classic=false;for(auto row:*rows.getArray()){auto file=juce::File(row.getProperty("file",{}).toString());std::unique_ptr<juce::AudioFormatReader> reader(formats.createReaderFor(file));if(!reader)throw std::runtime_error("cannot read example");AudioData data;data.path=file.getFullPathName();data.rate=reader->sampleRate;data.buffer.setSize(reader->numChannels,(int)reader->lengthInSamples);if(!reader->read(&data.buffer,0,data.buffer.getNumSamples(),0,true,true))throw std::runtime_error("read failed");double strength=(double)row.getProperty("strength",75),start=juce::Time::getMillisecondCounterHiRes();auto points=Processor::detectedPoints(data,0,data.buffer.getNumSamples(),strength);double ms=juce::Time::getMillisecondCounterHiRes()-start;auto* record=row.getDynamicObject();juce::Array<juce::var> times;for(int point:points)if(point>0&&point<data.buffer.getNumSamples())times.add(point/data.rate);record->setProperty("native",times);record->setProperty("native_ms",ms);start=juce::Time::getMillisecondCounterHiRes();std::set<int> prior;for(int sensitivity=0;sensitivity<=100;++sensitivity){auto detected=Processor::detectedPoints(data,0,data.buffer.getNumSamples(),sensitivity);std::set<int> current(detected.begin(),detected.end());for(int p:prior)if(!current.count(p))throw std::runtime_error("non-additive sensitivity");prior=std::move(current);}record->setProperty("cached_knob_ms",(juce::Time::getMillisecondCounterHiRes()-start)/101);auto alternate=Processor::detectedPoints(data,0,data.buffer.getNumSamples(),strength,73,1234,.5);if(points!=alternate)throw std::runtime_error("onsets incorrectly follow grid");results.add(row);std::cout<<file.getFileName()<<": "<<times.size()<<" cuts, analysis "<<ms<<" ms\n";}
 juce::File(output).replaceWithText(juce::JSON::toString(juce::var(results)));AudioData pulses;pulses.rate=48000;pulses.buffer.setSize(1,96000);pulses.buffer.clear();for(auto hit:std::vector<std::pair<int,float>>{{23300,.08f},{24000,.4f},{27600,.4f},{60000,.4f}})for(int n=0;n<400;++n)pulses.buffer.setSample(0,hit.first+n,hit.second);auto points=Processor::detectedPoints(pulses,0,96000,100);auto near=[&](int sample,int tolerance){return std::any_of(points.begin(),points.end(),[&](int p){return std::abs(p-sample)<tolerance;});};if(!near(24000,80)||!near(27600,80)||!near(60000,80)||near(23300,120)){std::cerr<<"Pulse onsets:";for(auto x:points)std::cerr<<" "<<x;throw std::runtime_error("stronger close attack or onset refinement");}
 AudioData stereo;stereo.rate=pulses.rate;stereo.buffer.setSize(2,96000);for(int n=0;n<96000;++n){float v=pulses.buffer.getSample(0,n);stereo.buffer.setSample(0,n,v);stereo.buffer.setSample(1,n,-v);}auto phase=Processor::detectedPoints(stereo,0,96000,100);if(phase!=points)throw std::runtime_error("stereo phase cancellation");AudioData silence;silence.rate=48000;silence.buffer.setSize(1,48000);silence.buffer.clear();if(Processor::detectedPoints(silence,0,48000,100).size()!=2)throw std::runtime_error("silence false positives");AudioData cancelled;cancelled.rate=48000;cancelled.buffer=pulses.buffer;if(!Processor::detectedPoints(cancelled,0,96000,100,120,0,.25,[]{return true;}).empty()||std::atomic_load(&cancelled.onsetMemo->data))throw std::runtime_error("cancelled analysis cache");for(auto row:results){auto name=juce::File(row.getProperty("file",{}).toString()).getFileName();if(name=="L 085 010.wav"){auto native=row.getProperty("native",{});for(double target:{60./85,180./85}){bool found=false;for(auto t:*native.getArray())if(std::abs((double)t-target)<.025)found=true;if(!found)throw std::runtime_error("reported snare still missing");}}}std::cout<<"All six examples, additive sensitivity, grid independence, stronger-close-hit suppression, hard-onset refinement, stereo phase, silence and cancellation passed.\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 4072;}}
